const stable=stats['recall-stable'],ref=stats['reference-visible'],off=stats['retention-off'];const growth=stable.meanMainContextChars-off.meanMainContextChars,tokenGrowth=ref.meanTotalTokens?(stable.meanTotalTokens-ref.meanTotalTokens)/ref.meanTotalTokens:0;
const decisions={b1_mechanism_and_autonomy:stable.recallAttemptRate>=.8&&stable.recallOkRate>=.95,b2_task_benefit:stable.evidenceSuccessRate-stats['baseline-no-reference'].evidenceSuccessRate>=.3&&comparisons['recall-stable_vs_baseline'].p<.05,b3_retention_benefit:comparisons['recall-stable_vs_retention-off'].onlyA>=1&&comparisons['recall-stable_vs_retention-off'].onlyB===0,b4_non_inferiority:stable.evidenceSuccessRate>=ref.evidenceSuccessRate-.05,b5_no_fabrication:stable.controlSuccessRate===1,b6_budget:growth<=16000&&tokenGrowth<=.25,contextGrowthChars:growth,tokenGrowthPct:tokenGrowth};same(decisions,summary.decision,'decision');
